// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.BinaryTupleOperator;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.junit.jupiter.api.Test;

/**
 * The SPARQL parser names anonymous variables (blank nodes, collections, path intermediates) with a counter in
 * query-text order. The canonical tie-break digest must therefore not depend on those generated names, or a textual
 * reordering of blank-node patterns renames them and flips the chosen plan among exactly tied alternatives.
 */
class PackedPlanAnonymousVariableOrderIndependenceTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void anonymousVariableNamesAssignedInTextOrderMustNotPickThePlan() {
		Map<String, Integer> plans = new TreeMap<>();
		for (List<String> permutation : permutations(List.of("p1", "p2", "p3", "p4"))) {
			TupleExpr query = null;
			for (int position = 0; position < permutation.size(); position++) {
				// the parser numbers blank nodes by their position in the query text
				StatementPattern pattern = new StatementPattern(Var.of("s"), constant(permutation.get(position)),
						Var.of("_anon_bnode_" + position, true));
				query = query == null ? pattern : new Join(query, pattern);
			}
			PackedPlanningResult result = PackedCascadesPlanner.optimize(query, OptimizationGoal.root(),
					(view, relationId) -> view.isStatementPattern(relationId) ? 100.0d : Double.NaN);
			plans.merge(order(result.selectedPlan()), 1, Integer::sum);
		}
		assertEquals(1, plans.size(),
				"blank-node star with equal estimates, 24 textual orders, several plans: " + plans);
	}

	@Test
	void anonymousVariableDigestStillDistinguishesConstants() {
		StatementPattern first = new StatementPattern(Var.of("s"), constant("p1"), Var.of("_anon_bnode_0", true));
		StatementPattern renamed = new StatementPattern(Var.of("s"), constant("p1"), Var.of("_anon_bnode_7", true));
		StatementPattern otherPredicate = new StatementPattern(Var.of("s"), constant("p2"),
				Var.of("_anon_bnode_0", true));

		assertEquals(PackedRelationDigest.digest(first), PackedRelationDigest.digest(renamed),
				"a generated anonymous name is not content");
		assertNotEquals(PackedRelationDigest.digest(first), PackedRelationDigest.digest(otherPredicate));
		assertNotEquals(PackedRelationDigest.digest(first),
				PackedRelationDigest.digest(new StatementPattern(Var.of("s"), constant("p1"), Var.of("o"))),
				"a named variable is not an anonymous one");
	}

	private static Var constant(String localName) {
		return Var.of("_const_" + localName, VF.createIRI("urn:" + localName), true, true);
	}

	private static List<List<String>> permutations(List<String> values) {
		List<List<String>> result = new ArrayList<>();
		permute(new ArrayList<>(values), 0, result);
		return result;
	}

	private static void permute(List<String> values, int offset, List<List<String>> result) {
		if (offset == values.size()) {
			result.add(List.copyOf(values));
			return;
		}
		for (int i = offset; i < values.size(); i++) {
			Collections.swap(values, offset, i);
			permute(values, offset + 1, result);
			Collections.swap(values, offset, i);
		}
	}

	private static String order(TupleExpr expr) {
		if (expr instanceof StatementPattern pattern) {
			return pattern.getPredicateVar().getValue().stringValue().substring("urn:".length());
		}
		if (expr instanceof BinaryTupleOperator binary) {
			return expr.getClass().getSimpleName() + "(" + order(binary.getLeftArg()) + ","
					+ order(binary.getRightArg()) + ")";
		}
		return expr.getClass().getSimpleName();
	}
}
